import { dateLabel, timestampLabel } from './i18n.js';
import { addDays, assetStatus, canExport, canInspect, canManage, dayDistance, dueSchedules, filteredAssets } from './domain.js';
import { assetArt, logoMark } from './icons.js';
import { avatar, badge, button, empty, h, icon, iconButton, notice, siteName, userName } from './ui.js';
export const pages = [['overview', 'grid'], ['assets', 'box'], ['inspections', 'clipboard'], ['schedules', 'calendar'], ['actions', 'wrench'], ['reports', 'report'], ['templates', 'layers'], ['team', 'users'], ['audit', 'clock'], ['help', 'help']];
export function shell(c, content) {
    const { state: s, t, route } = c;
    const active = route.startsWith('asset/') ? 'assets' : route;
    const nav = (from, to) => pages.slice(from, to).map(([page, glyph]) => `<a href="#/${page}" class="nav-item ${active === page ? 'selected' : ''}" ${active === page ? 'aria-current="page"' : ''}>${icon(glyph)}<span>${h(t(page))}</span>${page === 'actions' ? `<b>${s.findings.filter(f => f.status !== 'CLOSED').length}</b>` : ''}</a>`).join('');
    return `<a class="skip-link" href="#main">${h(t('overview'))}</a><div class="app-frame"><aside class="sidebar" aria-label="${h(t('menu'))}"><a class="brand" href="#/overview">${logoMark}<span>Pr\u00fcfPilot<small>${h(t('tagline'))}</small></span></a><div class="workspace-label">${h(t('workspace'))}</div><div class="workspace-switch">${avatar(s.organization.name)}<div><strong>${h(s.organization.name)}</strong><small>${h(t('liveWorkspace'))}</small></div><span class="online-dot"></span></div><div class="nav-label">${h(t('operations'))}</div><nav>${nav(0, 6)}</nav><div class="nav-label">${h(t('management'))}</div><nav>${nav(6, 10)}</nav><div class="sidebar-bottom"><div class="capacity"><span>${h(t('capacity'))}<strong>${s.assets.filter(a => !a.archived).length} / 250</strong></span><div class="progress"><i style="width:${Math.min(100, s.assets.filter(a => !a.archived).length / 2.5)}%"></i></div></div><button class="user-block" data-action="password">${avatar(s.user.displayName)}<span><strong>${h(s.user.displayName)}</strong><small>${h(t(s.user.role))}</small></span>${icon('settings')}</button></div></aside><div class="sidebar-scrim" data-action="menu"></div><div class="app-body"><header class="topbar">${iconButton(t('menu'), 'menu', 'menu')}<div class="breadcrumbs"><span>${h(s.organization.name)}</span>${icon('chevron')}<strong>${h(t(active))}</strong></div><button class="global-search" data-action="command">${icon('search')}<span>${h(t('search'))}</span><kbd>Ctrl K</kbd></button><div class="topbar-tools"><button class="lang-switch" data-action="language" title="${h(t('language'))}">${c.language.toUpperCase()}<span>${c.language === 'en' ? 'DE' : 'EN'}</span></button>${iconButton(t('theme'), 'theme', 'sun')}${iconButton(t('notifications'), 'reviews', 'bell')}<span class="topbar-divider"></span>${avatar(s.user.displayName, 'small')}${iconButton(t('signOut'), 'logout', 'logout')}</div></header>${c.preview ? `<div class="demo-strip"><span><i></i>${h(t('demoBanner'))}</span><div><label for="preview-role">${h(t('previewAs'))}</label><select id="preview-role" data-change="role">${['ADMIN', 'SUPERVISOR', 'INSPECTOR', 'TECHNICIAN', 'VIEWER'].map(r => `<option value="${r}" ${s.user.role === r ? 'selected' : ''}>${h(t(r))}</option>`).join('')}</select>${iconButton(t('resetPreview'), 'reset', 'refresh')}</div></div>` : s.demo ? `<div class="demo-strip">${h(t('demoData'))}</div>` : ''}<main id="main" tabindex="-1">${s.historyTruncated ? notice(t('truncated'), 'warning') : ''}${content}</main><footer class="app-footer"><span>${h(t('legalBoundary'))}</span><a href="https://ahadporkar.com/" target="_blank" rel="noopener noreferrer">${h(t('builtBy'))} ${icon('external')}</a></footer></div></div><dialog id="modal" aria-labelledby="modal-title"></dialog><div id="toast" role="status" aria-live="polite"></div>`;
}
function heading(c, title, subtitle, controls = '') { return `<section class="page-heading"><div><div class="eyebrow">${h(c.t('brand'))} / ${h(c.t('operations'))}</div><h1>${h(title)}</h1><p>${h(subtitle)}</p></div><div class="heading-actions">${controls}</div></section>`; }
function siteSelect(c) { return `<label class="site-filter">${icon('pin')}<select data-change="site" aria-label="${h(c.t('site'))}"><option value="">${h(c.t('allSites'))}</option>${c.state.sites.map(s => `<option value="${s.id}" ${c.site === s.id ? 'selected' : ''}>${h(s.name)}</option>`).join('')}</select></label>`; }
function dueText(c, due) { const days = dayDistance(c.state.today, due); return c.t(days < 0 ? 'daysOverdue' : days === 0 ? 'dueToday' : days === 1 ? 'tomorrow' : 'dueIn', { count: Math.abs(days) }); }
function inspectionTable(c, records) {
    const { state: s, t, language: l } = c;
    return records.length ? `<div class="table-scroll"><table><thead><tr><th>${h(t('asset'))}</th><th>${h(t('template'))}</th><th>${h(t('inspector'))}</th><th>${h(t('due'))}</th><th>${h(t('status'))}</th><th><span class="sr-only">${h(t('view'))}</span></th></tr></thead><tbody>${records.map(i => `<tr><td><button class="text-link" data-action="inspection" data-id="${i.id}">${h(s.assets.find(a => a.id === i.assetId)?.name)}</button><small>${h(s.assets.find(a => a.id === i.assetId)?.code)}</small></td><td>${h(templateName(c, i.templateId))}</td><td><span class="person">${avatar(userName(s, i.inspectorId), 'tiny')}${h(userName(s, i.inspectorId))}</span></td><td>${dateLabel(i.plannedDue ?? i.createdAt, l)}</td><td>${badge(i.status, t)}</td><td>${iconButton(t('view'), 'inspection', 'arrow', i.id)}</td></tr>`).join('')}</tbody></table></div>` : empty(t('noResults'), t('noResultsHint'), 'clipboard');
}
function templateName(c, id) { const template = c.state.templates.find(t => t.id === id); return (c.language === 'de' ? template?.nameDe : template?.name) ?? '\u2014'; }
function timeline(c, limit = 6) { const events = (c.passport?.audit ?? c.state.audit).slice(0, limit); return events.length ? `<div class="timeline">${events.map(e => `<article><span class="timeline-marker">${icon(e.action.includes('VERIFY') ? 'check' : e.action.includes('EVIDENCE') ? 'file' : 'clock')}</span><div><strong>${h(c.t(e.action))}</strong><p>${h(e.detail)}</p><small>${h(e.actorName)} <span>\u00b7</span> ${timestampLabel(e.occurredAt, c.language, c.state.organization.timezone)}</small></div></article>`).join('')}</div>` : empty(c.t('noActivity')); }
export function overview(c) {
    const { state: s, t } = c;
    const assets = s.assets.filter(a => !a.archived && (!c.site || a.siteId === c.site));
    const ids = new Set(assets.map(a => a.id));
    const due = dueSchedules(s, c.site);
    const upcoming = due.filter(d => d.nextDue <= addDays(s.today, 7));
    const findings = s.findings.filter(f => ids.has(f.assetId) && f.status !== 'CLOSED');
    const pending = s.inspections.filter(i => ids.has(i.assetId) && i.status === 'SUBMITTED').length + s.findings.filter(f => ids.has(f.assetId) && f.status === 'AWAITING_VERIFICATION').length;
    const coverage = assets.length ? Math.round(new Set(due.map(d => d.assetId)).size / assets.length * 100) : 0;
    const cards = [['activeAssets', assets.length, 'box', t('acrossSites', { count: c.site ? 1 : s.sites.length }), 'assets'], ['dueWeek', upcoming.length, 'calendar', t('includesOverdue', { count: due.filter(d => d.nextDue < s.today).length }), 'schedules'], ['openActions', findings.length, 'wrench', t('closureRequired'), 'actions'], ['awaitingReview', pending, 'shield', t('independentReviewLabel'), 'inspections']];
    return `<section class="page-heading overview-heading"><div><div class="eyebrow">${h(t('overviewEyebrow'))}</div><h1>${h(t('hello', { name: s.user.displayName.split(' ')[0] ?? '' }))}</h1><p>${h(t('overviewSubtitle'))}</p></div><div class="heading-actions">${siteSelect(c)}${iconButton(t('scan'), 'scan', 'qr')}${canInspect(s.user.role) ? button(t('newInspection'), 'new-inspection', '', 'primary', 'plus') : ''}</div></section><section class="kpi-grid">${cards.map(([title, value, glyph, hint, page], idx) => `<a class="kpi kpi-${idx}" href="#/${page}"><div><span>${h(t(String(title)))}</span>${icon(String(glyph))}</div><strong>${value}<span>${icon('arrow')}</span></strong><small>${h(hint)}</small></a>`).join('')}</section><section class="hero"><div class="hero-copy"><span class="eyebrow">${icon('spark')}${h(t('assetIntelligence'))}</span><h2>${h(t('portfolioTitle')).replace('\n', '<br>')}</h2><p>${h(t('portfolioSubtitle')).replace('\n', '<br>')}</p><a class="btn btn-lime" href="#/assets">${h(t('explorePassports'))}${icon('arrow')}</a><div class="hero-caption"><span class="live-dot"></span>${h(t('closureRequired'))}</div></div><div class="hero-visual"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div>${assetArt()}<div class="floating-label label-top">${icon('qr')}<div><small>${h(t('assetIdentity'))}</small><strong>${h(assets[0]?.code ?? 'PP-001')}</strong></div></div><div class="floating-label label-bottom"><span class="verified-seal">${icon('shield')}</span><div><strong>${h(t('independentReviewLabel'))}</strong><small>${h(t('legalBoundary'))}</small></div></div><span class="art-index">FIG. 01 / ASSET PASSPORT</span></div></section><section class="dashboard-lower"><div class="panel due-panel"><div class="panel-heading"><div><h2>${h(t('attentionTitle'))}<span class="count">${upcoming.length}</span></h2><p>${h(t('attentionSubtitle'))}</p></div><a class="text-link" href="#/schedules">${h(t('viewAll'))}${icon('arrow')}</a></div><div class="due-list">${due.slice(0, 5).map(d => { const a = assets.find(a => a.id === d.assetId); return `<article class="due-row"><span class="asset-mini">${icon('box')}</span><div class="due-info"><a href="#/asset/${a.id}">${h(a.name)}</a><small>${h(a.code)} <span>\u00b7</span> ${h(siteName(s, a.siteId))}</small></div><div class="due-date ${d.nextDue < s.today ? 'late' : ''}"><strong>${h(dueText(c, d.nextDue))}</strong><small>${h(templateName(c, d.templateId))}</small></div>${canInspect(s.user.role) ? iconButton(t('startInspection'), 'start-scheduled', 'arrow', d.id) : ''}</article>`; }).join('') || empty(t('noDue'))}</div></div><div class="panel readiness"><div class="panel-heading"><h2>${h(t('readiness'))}</h2>${icon('shield')}</div><div class="coverage-ring" style="--coverage:${coverage}%"><div><strong>${coverage}<small>%</small></strong><span>${h(t('scheduledAssets'))}</span></div></div><p>${h(t('readinessHint'))}</p><div class="coverage-legend"><span><i></i>${h(t('scheduled'))}</span><strong>${new Set(due.map(d => d.assetId)).size} / ${assets.length}</strong></div></div></section><section class="dashboard-bottom"><div class="panel"><div class="panel-heading"><div><h2>${h(t('nextSeven'))}</h2><p>${h(t('checksScheduled'))}</p></div>${icon('calendar')}</div><div class="week-chart" role="img" aria-label="${h(t('checksScheduled'))}">${Array.from({ length: 7 }, (_, i) => { const date = addDays(s.today, i); const count = due.filter(d => d.nextDue === date).length; const max = Math.max(1, ...Array.from({ length: 7 }, (_, j) => due.filter(d => d.nextDue === addDays(s.today, j)).length)); return `<div class="day-column"><strong>${count}</strong><div class="bar-track"><span style="height:${count ? Math.max(8, count / max * 100) : 3}%"></span></div><small>${dateLabel(date, c.language)}</small></div>`; }).join('')}</div></div><div class="panel"><div class="panel-heading"><h2>${h(t('recentActivity'))}</h2><a class="text-link" href="#/audit">${h(t('viewLog'))}${icon('arrow')}</a></div>${timeline(c, 3)}</div></section>`;
}
export function assetsView(c) {
    const { t, state: s } = c;
    const assets = filteredAssets(s, c.query, c.site, c.category);
    return heading(c, t('assets'), t('assetSubtitle'), `${canManage(s.user.role) ? button(t('newSite'), 'new-site', '', 'secondary', 'pin') + button(t('newAsset'), 'new-asset', '', 'primary', 'plus') : ''}`) + `<section class="filterbar"><label class="search-field">${icon('search')}<input data-input="asset-search" value="${h(c.query)}" placeholder="${h(t('filterAssets'))}" aria-label="${h(t('filterAssets'))}"></label>${siteSelect(c)}<select data-change="category" aria-label="${h(t('category'))}"><option value="">${h(t('allCategories'))}</option>${[...new Set(s.assets.map(a => a.category))].sort().map(cat => `<option ${cat === c.category ? 'selected' : ''}>${h(cat)}</option>`).join('')}</select><div class="segmented">${iconButton(t('grid'), 'grid', 'grid')}${iconButton(t('table'), 'table', 'list')}</div></section><div class="section-caption">${h(t('assetCount', { count: assets.length }))}<span>${h(t('legalBoundary'))}</span></div>` + (assets.length ? (c.layout === 'table' ? `<div class="panel table-scroll"><table><thead><tr><th>${h(t('asset'))}</th><th>${h(t('site'))}</th><th>${h(t('category'))}</th><th>${h(t('status'))}</th><th></th></tr></thead><tbody>${assets.map(a => `<tr><td><a class="text-link" href="#/asset/${a.id}">${h(a.name)}</a><small>${h(a.code)}</small></td><td>${h(siteName(s, a.siteId))}</td><td>${h(a.category)}</td><td>${badge(assetStatus(a, s), t)}</td><td><a class="icon-btn" href="#/asset/${a.id}" aria-label="${h(t('passport'))}">${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>` : `<section class="asset-grid">${assets.map((a, idx) => assetCard(c, a, idx)).join('')}</section>`) : empty(t('noResults'), t('noResultsHint')));
}
function assetCard(c, a, index) {
    const { state: s, t } = c;
    const next = s.schedules.filter(x => x.assetId === a.id && x.active).sort((a, b) => a.nextDue.localeCompare(b.nextDue))[0];
    const open = s.findings.filter(f => f.assetId === a.id && f.status !== 'CLOSED').length;
    return `<a class="asset-card" href="#/asset/${a.id}"><div class="asset-card-top"><span class="asset-glyph asset-tone-${index % 4}">${icon(index % 3 === 0 ? 'box' : index % 3 === 1 ? 'settings' : 'layers')}</span>${badge(assetStatus(a, s), t)}</div><span class="mono asset-code">${h(a.code)}</span><h3>${h(a.name)}</h3><p>${icon('pin')}${h(siteName(s, a.siteId))}</p><div class="asset-card-stats"><div><small>${h(t('nextInspection'))}</small><strong>${next ? dateLabel(next.nextDue, c.language) : '\u2014'}</strong></div><div><small>${h(t('openActions'))}</small><strong>${open.toString().padStart(2, '0')}</strong></div></div><div class="asset-card-footer"><span>${h(a.category)}</span><span>${h(t('passport'))}${icon('arrow')}</span></div></a>`;
}
export function passportView(c) {
    const p = c.passport;
    if (!p)
        return empty(c.t('loading'));
    const { state: s, t } = c;
    const a = p.asset;
    const active = s.schedules.filter(x => x.assetId === a.id && x.active).sort((a, b) => a.nextDue.localeCompare(b.nextDue));
    const open = p.findings.filter(f => f.status !== 'CLOSED');
    const last = p.inspections.find(i => i.status === 'VERIFIED');
    return `<a class="back-link" href="#/assets">${icon('back')}${h(t('assets'))}</a>` + heading(c, a.name, t('passportIntro'), `${button(t('print'), 'qr', a.id, 'secondary', 'qr')}${canExport(s.user.role) ? button(t('export'), 'export', a.id, 'secondary', 'download') : ''}${canInspect(s.user.role) && !a.archived ? button(t('newInspection'), 'new-inspection', a.id, 'primary', 'plus') : ''}`) + `<section class="passport-hero"><div class="passport-art"><span class="eyebrow">${h(t('assetIdentity'))}</span>${assetArt()}<div class="passport-code mono">${h(a.code)}${icon('qr')}</div></div><div class="passport-info"><div class="passport-topline">${badge(assetStatus(a, s), t)}<span class="mono">${h(a.category)}</span></div><h2>${h(a.manufacturer)} <span>${h(a.model)}</span></h2><p>${icon('pin')}${h(siteName(s, a.siteId))} \u00b7 ${h(a.locationNote)}</p><dl class="metadata-grid"><div><dt>${h(t('serial'))}</dt><dd class="mono">${h(a.serialNumber) || '\u2014'}</dd></div><div><dt>${h(t('criticality'))}</dt><dd>${badge(a.criticality, t)}</dd></div><div><dt>${h(t('lastInspection'))}</dt><dd>${last ? dateLabel(last.performedAt, c.language, true) : h(t('neverInspected'))}</dd></div><div><dt>${h(t('nextInspection'))}</dt><dd>${active[0] ? dateLabel(active[0].nextDue, c.language, true) : h(t('noSchedule'))}</dd></div></dl><div class="passport-footer"><span>${icon('shield')}${h(t('legalBoundary'))}</span>${canManage(s.user.role) && !a.archived ? button(t('archive'), 'archive', a.id, 'ghost') : ''}</div></div></section><section class="passport-stats"><div>${icon('clipboard')}<strong>${p.inspections.length}${p.hasMore ? '+' : ''}</strong><span>${h(t('inspections'))}</span></div><div>${icon('wrench')}<strong>${open.length}</strong><span>${h(t('openActions'))}</span></div><div>${icon('file')}<strong>${p.evidence.length}</strong><span>${h(t('evidence'))}</span></div></section><section class="panel"><div class="panel-heading"><h2>${h(t('history'))}</h2><span class="eyebrow">${h(t('passport'))}</span></div>${inspectionTable(c, p.inspections)}${p.hasMore ? `<div class="panel-footer">${button(t('olderInspections'), 'older-inspections', a.id)}</div>` : ''}</section><section class="dashboard-bottom"><div class="panel"><div class="panel-heading"><h2>${h(t('openActions'))}</h2><span class="count">${open.length}</span></div>${open.length ? open.map(f => `<button class="finding-row" data-action="finding" data-id="${f.id}"><span>${badge(f.severity, t)}</span><div><strong>${h(f.title)}</strong><small>${h(userName(s, f.assigneeId))} \u00b7 ${h(t(f.status))}</small></div>${icon('arrow')}</button>`).join('') : empty(t('noFindings'), '', 'shield')}</div><div class="panel"><div class="panel-heading"><h2>${h(t('evidence'))}</h2><span class="count">${p.evidence.length}</span></div>${evidenceList(c, p.evidence)}</div></section><section class="panel"><div class="panel-heading"><h2>${h(t('timeline'))}</h2></div>${timeline(c, 12)}</section>`;
}
export function evidenceList(c, files) { return files.length ? `<div class="evidence-list">${files.map(f => `<button class="evidence-row" data-action="download-evidence" data-id="${f.id}">${icon(f.mime.startsWith('image/') ? 'image' : 'file')}<span><strong>${h(f.filename)}</strong><small>${(f.size / 1024).toFixed(1)} KiB \u00b7 ${h(userName(c.state, f.uploadedBy))}</small></span>${icon('download')}</button>`).join('')}</div>` : empty(c.t('noEvidence'), '', 'file'); }
export function inspectionsView(c) { return heading(c, c.t('inspections'), c.t('inspectionSubtitle'), canInspect(c.state.user.role) ? button(c.t('newInspection'), 'new-inspection', '', 'primary', 'plus') : '') + `<div class="section-caption">${h(c.t('inspectionCount', { count: c.state.inspections.length }))}${siteSelect(c)}</div><section class="panel">${inspectionTable(c, c.state.inspections.filter(i => !c.site || c.state.assets.find(a => a.id === i.assetId)?.siteId === c.site))}</section>`; }
export function schedulesView(c) {
    const { state: s, t } = c;
    const records = s.schedules.filter(x => !c.site || s.assets.find(a => a.id === x.assetId)?.siteId === c.site).sort((a, b) => Number(b.active) - Number(a.active) || a.nextDue.localeCompare(b.nextDue));
    return heading(c, t('schedules'), t('scheduleSubtitle'), canManage(s.user.role) ? button(t('newSchedule'), 'new-schedule', '', 'primary', 'plus') : '') + notice(t('noStatutoryIntervals')) + `<div class="section-caption">${h(t('schedules'))}${siteSelect(c)}</div><div class="panel table-scroll"><table><thead><tr><th>${h(t('asset'))}</th><th>${h(t('template'))}</th><th>${h(t('due'))}</th><th>${h(t('intervalDays'))}</th><th>${h(t('owner'))}</th><th>${h(t('status'))}</th><th></th></tr></thead><tbody>${records.map(r => `<tr><td><a class="text-link" href="#/asset/${r.assetId}">${h(s.assets.find(a => a.id === r.assetId)?.name)}</a><details><summary>${h(t('scheduleBasis'))}</summary><p>${h(r.reason)}</p><small>${h(t('reviewedBy'))}: ${h(userName(s, r.reviewedBy))}</small></details></td><td>${h(templateName(c, r.templateId))}</td><td><strong class="${r.active && r.nextDue < s.today ? 'text-danger' : ''}">${dateLabel(r.nextDue, c.language)}</strong><small>${r.active ? h(dueText(c, r.nextDue)) : h(t('paused'))}</small></td><td><span class="interval-number">${r.intervalDays}</span> ${h(t('days'))}</td><td>${h(userName(s, r.ownerId))}</td><td>${badge(r.active ? 'ACTIVE' : 'PAUSED', t)}</td><td><div class="row-actions">${r.active && canInspect(s.user.role) ? iconButton(t('startInspection'), 'start-scheduled', 'play', r.id) : ''}${r.active && canManage(s.user.role) ? button(t('pause'), 'pause', r.id, 'ghost') : ''}</div></td></tr>`).join('')}</tbody></table>${!records.length ? empty(t('schedulesEmpty'), t('createScheduleHint')) : ''}</div>`;
}
export function actionsView(c) { const { state: s, t } = c; const statuses = ['OPEN', 'IN_PROGRESS', 'AWAITING_VERIFICATION', 'CLOSED']; return heading(c, t('actions'), t('actionsSubtitle')) + `<div class="section-caption">${h(t('actionCount', { count: s.findings.length }))}${siteSelect(c)}</div><section class="kanban">${statuses.map((status, idx) => { const list = s.findings.filter(f => f.status === status && (!c.site || s.assets.find(a => a.id === f.assetId)?.siteId === c.site)); return `<div class="kanban-column"><div class="kanban-heading"><span class="stage-dot stage-${idx}"></span><h2>${h(t(status))}</h2><span>${list.length}</span></div><div class="kanban-cards">${list.map(f => `<button class="action-card" data-action="finding" data-id="${f.id}"><div>${badge(f.severity, t)}${icon('arrow')}</div><span class="mono">${h(s.assets.find(a => a.id === f.assetId)?.code)}</span><h3>${h(f.title)}</h3><p>${h(f.description)}</p><div class="action-card-asset">${icon('box')}${h(s.assets.find(a => a.id === f.assetId)?.name)}</div><footer><span class="person">${f.assigneeId ? avatar(userName(s, f.assigneeId), 'tiny') : icon('users')}${h(f.assigneeId ? userName(s, f.assigneeId).split(' ')[0] : t('unassigned'))}</span><span>${f.dueDate ? dateLabel(f.dueDate, c.language) : '\u2014'}</span></footer></button>`).join('') || `<div class="kanban-empty">${icon('check')}<span>${h(t('emptyColumn'))}</span></div>`}</div></div>`; }).join('')}</section>`; }
